window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-10-05","title":"Ethics Application","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[265,301],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[200,209],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[224,249],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-10-05-LOS01","learning_goal_vi":"Đánh giá practices, policies và conduct so với Code và Standards của CFA Institute.","status":"targeted_CFAI_Kaplan_SAPP_and_vignette_QA_pass","competency_criteria":["Phân tích facts theo bộ Ethics CFA 2026","Nhận biết và giải thích multiple applicable Standards","Tình huống conforming/violating, exceptions, timing và disclosure","Gắn 14 ví dụ/câu hỏi mới và 8 checklists giải pháp"],"concept_ids":["S01-01","S01-02","S01-03","S01-04","S01-05","S01-06","S01-07","S01-08"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02","E01-03","E01-04","E01-05","E01-06","E01-07","E01-08","E01-09","E01-10","E01-11","E01-12","E01-13","E01-14"],"question_ids":["Q01-01","Q01-02","Q01-03","Q01-04","Q01-05","Q01-06","Q01-07","Q01-08","Q01-09","Q01-10","Q01-11","Q01-12","Q01-13","Q01-14"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":265},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":200},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":225}},"missing_items":[]},{"los_id":"CFA26-10-05-LOS02","learning_goal_vi":"Giải thích vì sao một hành vi tuân thủ hoặc vi phạm Code và Standards.","status":"targeted_CFAI_Kaplan_SAPP_and_vignette_QA_pass","competency_criteria":["Phân tích facts theo bộ Ethics CFA 2026","Nhận biết và giải thích multiple applicable Standards","Tình huống conforming/violating, exceptions, timing và disclosure","Gắn 14 ví dụ/câu hỏi mới và 8 checklists giải pháp"],"concept_ids":["S02-01","S02-02","S02-03","S02-04","S02-05","S02-06","S02-07","S02-08"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02","E02-03","E02-04","E02-05","E02-06","E02-07","E02-08","E02-09","E02-10","E02-11","E02-12","E02-13","E02-14"],"question_ids":["Q02-01","Q02-02","Q02-03","Q02-04","Q02-05","Q02-06","Q02-07","Q02-08","Q02-09","Q02-10","Q02-11","Q02-12","Q02-13","Q02-14"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":275},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":200},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":225}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 1: xác định sự kiện và chủ thể","body_vi":"Ở mỗi vignette, trước tiên tách facts đã được cung cấp, assumptions, thời điểm hành vi và vai trò người tham gia: member/candidate, client, employer, counterparties và issuer. Cùng một lời đề nghị quà tặng có thể bị đánh giá khác tùy tính chất, giá trị, timing và ảnh hưởng thực tế tới independence."},{"id":"S01-02","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 2: xác định applicable duties","body_vi":"Đặt nghĩa vụ Code/Standards và applicable laws lên từng hành vi. Không chỉ tìm từ “conflict” mà cần xác định nghĩa vụ ưu tiên client, duty to employer, market integrity, professional judgment và có hành vi nào thuộc II(A), III(C), IV(B), V(A) hoặc VI(A)."},{"id":"S01-03","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 3: tách facts và hậu quả","body_vi":"Xác định information public hay nonpublic, materiality, kiểu giao dịch, có intentional market deception, client suitability và trade allocation hay không. Không suy luận “vi phạm” chỉ từ việc sản phẩm giảm giá: loss có thể xảy ra dù process và suitability đã đúng."},{"id":"S01-04","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 4: kiểm tra disclosure, consent và timing","body_vi":"Disclosure phải đủ và rõ; không phải cứ có một disclaimer là đã đáp ứng. Written consent của tất cả bên liên quan là yêu cầu riêng đối với IV(B); VI(A) yêu cầu avoid hoặc full/fair disclosure; III(E) có ngoại lệ theo law, illegal activities hoặc consent."},{"id":"S01-05","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 5: nguyên tắc multi-standard","body_vi":"Nếu cùng một nhân viên nhận hidden referral fee, front-run client order và giấu material risk, cần đánh giá VI(C), VI(B), V(B) và III(A) độc lập. Chọn đáp án “best” dựa trên facts và nghĩa vụ ưu tiên, không lựa một Standard duy nhất để bỏ qua những vi phạm còn lại."},{"id":"S01-06","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 6: biện pháp khắc phục","body_vi":"Hành động đúng thường gồm tránh hoạt động gây xung đột, compliance escalation, independent research review, material disclosure, lưu hồ sơ, phù hợp IPS và ưu tiên client orders. Trong câu CFA, hành động “xin lỗi sau đó” hoặc “nói chung là tuân thủ” không đủ nếu không sửa tác động lên client."},{"id":"S01-07","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 7: quyền hạn và compliance culture","body_vi":"Professional conduct không chỉ thuộc nhân viên trực tiếp: supervisor phải duy trì reasonable oversight, firm cần ethical culture và incentive. Một môi trường có manual trên giấy nhưng biết nhân viên gian lận và không khắc phục vẫn có governance failure."},{"id":"S01-08","los_ids":["CFA26-10-05-LOS01"],"heading_vi":"Bước 8: trade-offs với lợi nhuận","body_vi":"Đạo đức không bảo đảm mọi khuyến nghị sinh lời; hiệu quả đầu tư xấu sau khi market moves không tự động là misconduct. Thẩm định hành vi nên đánh giá quality of information, process, disclosures, basis, suitability và professional judgment vào lúc quyết định."},{"id":"S02-01","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Các yếu tố biến một hành vi thành violation","body_vi":"Phân biệt đã có material nonpublic info (II(A)) với mosaic dựa public + nonmaterial private info; phân biệt market-making hợp pháp với spoofing nhằm gây hiểu nhầm. Những chi tiết nhỏ về materiality, intent và timing thường quyết định kết luận."},{"id":"S02-02","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Quyết định conforming không có nghĩa không rủi ro","body_vi":"Một manager có thể mất tiền trên danh mục nhưng vẫn tuân Standards khi đã đánh giá risk tolerance, investment horizon, data research và risk disclosures đúng. Ngược lại một recommendation sinh lời lớn có thể vẫn vi phạm do front-running, hidden conflicts hoặc thiếu reasonable basis."},{"id":"S02-03","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Consent không thay thế tất cả duties","body_vi":"Được khách hàng đồng ý một referral fee không miễn written consent required under IV(B) nếu arrangement gây conflict với employer. Disclosure VI(A) không chữa được insider trading II(A), và NDA với agency cũng không tự động tạo ngoại lệ confidentiality III(E)."},{"id":"S02-04","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Thứ tự thời gian giao dịch quan trọng","body_vi":"VI(B) priority yêu cầu client/employer trades trước personal beneficial ownership; trade nhỏ có thể vẫn front-run. Các lệnh personal preclearance và order timestamps cho thấy process, nhưng dù không làm giá biến động thì front-running vẫn trái chuẩn."},{"id":"S02-05","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Ngoại lệ và những trường hợp hợp pháp","body_vi":"III(E) cho phép disclosure khi law requires/client permits/illegal activities; I(A) áp dụng strictest relevant requirement; VII(A) vẫn cho phép candidate nêu nhận xét chung về exam, nhưng không tiết lộ confidential questions. Các ngoại lệ này cần đọc đúng facts."},{"id":"S02-06","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Phân biệt duties theo đối tượng","body_vi":"III(A) Loyalty to Client khác IV(A) Loyalty to Employer; client interest được ưu tiên khi quản lý tài sản, nhưng employee vẫn không được lấy cắp client records khi chuyển việc. Dữ liệu thuộc employer trong employment context không tự thành tài sản riêng analyst."},{"id":"S02-07","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Disclosure effective","body_vi":"V(B) phải công bố nature of services, costs, methodology, material changes, significant limitations và fact/opinion distinction. VI(A) ưu tiên tránh conflict hoặc full/fair disclosure prominent and plain; VI(C) disclose referral compensation. Một dòng mơ hồ hiếm khi giải quyết cả ba."},{"id":"S02-08","los_ids":["CFA26-10-05-LOS02"],"heading_vi":"Cách chọn best answer","body_vi":"Đối với ba phương án CFA, tìm hành động xử lý đúng bản chất ngay trước giao dịch, có thể triển khai và không làm tổn hại duty khác. Loại phương án cho rằng “không có vi phạm vì luật cho phép”, “không mất tiền nên được phép” hoặc “đã ghi mơ hồ là đủ”."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-10-05-LOS01"],"expression":"Case evaluation = facts + applicable standards + exception/consent/timing + stakeholder duties + compliant action","variables":["This is an instructional checklist, not a numerical CFA valuation formula."],"assumptions":["Ethics is case-specific; resolve conflicting applicable laws/standards using the stricter duty."]},{"id":"F02-01","los_ids":["CFA26-10-05-LOS02"],"expression":"Case evaluation = facts + applicable standards + exception/consent/timing + stakeholder duties + compliant action","variables":["This is an instructional checklist, not a numerical CFA valuation formula."],"assumptions":["Ethics is case-specific; resolve conflicting applicable laws/standards using the stricter duty."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette I(A): Một bộ phận Việt Nam xử lý giao dịch tại thị trường nước ngoài nơi regulation cấm phân phối cho retail; công ty mẹ muốn dùng chuẩn thị trường khác ít nghiêm hơn.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(A).","Áp dụng đúng yêu cầu I(A) và phân biệt với phương án dễ mắc lỗi: Áp dụng quy định lỏng nhất để chạy kịp chỉ tiêu.","Hành động phù hợp có thể kiểm chứng: Từ chối phát hành tới retail thuộc jurisdiction hạn chế; xác định applicable laws và dùng chuẩn nghiêm hơn, tìm legal counsel."],"answer":"Chuẩn liên quan I(A). Từ chối phát hành tới retail thuộc jurisdiction hạn chế; xác định applicable laws và dùng chuẩn nghiêm hơn, tìm legal counsel."},{"id":"E01-02","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette I(B): Issuer đề nghị research analyst một chuyến công tác “khảo sát” ở resort năm sao và hứa giao thêm deal nếu rating là buy.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(B).","Áp dụng đúng yêu cầu I(B) và phân biệt với phương án dễ mắc lỗi: Chấp nhận chuyến đi vì issuer nói đây là quà phổ biến.","Hành động phù hợp có thể kiểm chứng: Từ chối hospitality có thể làm ảnh hưởng objectivity; sắp xếp visit theo chính sách độc lập và ghi nhận conflict."],"answer":"Chuẩn liên quan I(B). Từ chối hospitality có thể làm ảnh hưởng objectivity; sắp xếp visit theo chính sách độc lập và ghi nhận conflict."},{"id":"E01-03","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette I(C): Analyst sửa đường dự báo Excel của nhà tư vấn thành “mô hình độc quyền của tôi” và nói return chắc chắn 18%.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(C).","Áp dụng đúng yêu cầu I(C) và phân biệt với phương án dễ mắc lỗi: Dùng lời cam kết vì historical return 18% trong một năm.","Hành động phù hợp có thể kiểm chứng: Ghi đúng provenance, giữ assumptions và trình bày returns như forecast có uncertainty, không guarantee."],"answer":"Chuẩn liên quan I(C). Ghi đúng provenance, giữ assumptions và trình bày returns như forecast có uncertainty, không guarantee."},{"id":"E01-04","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette I(E): Chuyên viên chuyên equity được chuyển phân tích autocallable note; chưa hiểu barriers nhưng được yêu cầu ký valuation ngay.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(E).","Áp dụng đúng yêu cầu I(E) và phân biệt với phương án dễ mắc lỗi: Ký report rồi học thêm sau vì đã làm CFA Level I.","Hành động phù hợp có thể kiểm chứng: Không ký khi chưa đủ competence; tham vấn chuyên gia/đào tạo, validate risk và model trước khi dùng."],"answer":"Chuẩn liên quan I(E). Không ký khi chưa đủ competence; tham vấn chuyên gia/đào tạo, validate risk và model trước khi dùng."},{"id":"E01-05","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette II(A): Một nguồn nội bộ cho biết thương vụ mua lại sẽ công bố tuần sau, có khả năng đổi giá cổ phiếu, analyst chưa giao dịch.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến II(A).","Áp dụng đúng yêu cầu II(A) và phân biệt với phương án dễ mắc lỗi: Mua cho tài khoản gia đình vì thông tin chưa xuất hiện trên báo chí.","Hành động phù hợp có thể kiểm chứng: Không trading/tipping theo material nonpublic information; báo compliance và chờ public dissemination."],"answer":"Chuẩn liên quan II(A). Không trading/tipping theo material nonpublic information; báo compliance và chờ public dissemination."},{"id":"E01-06","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette II(B): Trader tung các lệnh mua lớn rồi hủy nhanh, mục đích làm người khác tưởng cổ phiếu có demand, sau đó bán hàng đang giữ.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến II(B).","Áp dụng đúng yêu cầu II(B) và phân biệt với phương án dễ mắc lỗi: Tiếp tục vì cuối cùng không khớp các lệnh mua ảo.","Hành động phù hợp có thể kiểm chứng: Không tạo deceptive orders/volume; dừng strategy có intent manipulation và báo surveillance."],"answer":"Chuẩn liên quan II(B). Không tạo deceptive orders/volume; dừng strategy có intent manipulation và báo surveillance."},{"id":"E01-07","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette III(A): Portfolio manager chọn broker affiliate với cost cao và execution chậm dù công ty độc lập có giá thực thi tốt hơn.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(A).","Áp dụng đúng yêu cầu III(A) và phân biệt với phương án dễ mắc lỗi: Ưu tiên affiliate vì phí giúp tăng doanh thu employer.","Hành động phù hợp có thể kiểm chứng: Đánh giá best execution/client benefit net of costs; tránh giao dịch do quan hệ cá nhân không được công bố."],"answer":"Chuẩn liên quan III(A). Đánh giá best execution/client benefit net of costs; tránh giao dịch do quan hệ cá nhân không được công bố."},{"id":"E01-08","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette III(B): Một khuyến nghị thay đổi từ hold sang sell được gửi riêng cho clients trả phí cao trước một ngày so với nhóm cùng loại research.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(B).","Áp dụng đúng yêu cầu III(B) và phân biệt với phương án dễ mắc lỗi: Thông báo riêng VIP vì nhóm này đáng được bảo vệ hơn.","Hành động phù hợp có thể kiểm chứng: Phân phối fair và objective theo policy/entitlements hợp lý, không tạo thiên vị không phù hợp."],"answer":"Chuẩn liên quan III(B). Phân phối fair và objective theo policy/entitlements hợp lý, không tạo thiên vị không phù hợp."},{"id":"E01-09","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette III(C): Khách cần chi phí học phí năm sau nhưng adviser đặt 70% tài sản vào closed-end fund khó rút trong 7 năm.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(C).","Áp dụng đúng yêu cầu III(C) và phân biệt với phương án dễ mắc lỗi: Khuyên đầu tư vì expected IRR cao nên suitability tự động thỏa mãn.","Hành động phù hợp có thể kiểm chứng: Xác minh liquidity needs, horizon và tổng portfolio; chỉ recommend asset phù hợp toàn bộ constraints."],"answer":"Chuẩn liên quan III(C). Xác minh liquidity needs, horizon và tổng portfolio; chỉ recommend asset phù hợp toàn bộ constraints."},{"id":"E01-10","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette III(D): Fund marketing loại bỏ hai tài khoản bị đóng vì lỗ khỏi track record, báo “average năm nay +20%”.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(D).","Áp dụng đúng yêu cầu III(D) và phân biệt với phương án dễ mắc lỗi: Chỉ báo cáo số còn active vì tài khoản đóng không còn là client.","Hành động phù hợp có thể kiểm chứng: Tổng hợp performance fair, accurate, complete theo policy; không cherry-pick accounts/periods."],"answer":"Chuẩn liên quan III(D). Tổng hợp performance fair, accurate, complete theo policy; không cherry-pick accounts/periods."},{"id":"E01-11","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette III(E): Advisor gửi bảng clients giàu có cùng số tài khoản cho agency marketing ngoài công ty mà không xin consent.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(E).","Áp dụng đúng yêu cầu III(E) và phân biệt với phương án dễ mắc lỗi: Gửi vì data dùng cho bán hàng và agency có NDA.","Hành động phù hợp có thể kiểm chứng: Giữ confidentiality và chỉ chia sẻ khi có client permission, legal requirement hoặc exception hợp lệ."],"answer":"Chuẩn liên quan III(E). Giữ confidentiality và chỉ chia sẻ khi có client permission, legal requirement hoặc exception hợp lệ."},{"id":"E01-12","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette IV(B): Advisor được một khách lớn hứa bonus cá nhân nếu danh mục vượt benchmark, nhưng chưa xin written permission employer.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến IV(B).","Áp dụng đúng yêu cầu IV(B) và phân biệt với phương án dễ mắc lỗi: Nhận tiền và tiết lộ vào cuối năm khi đã hoàn thành mục tiêu.","Hành động phù hợp có thể kiểm chứng: Xin written consent của mọi bên liên quan trước khi nhận additional compensation arrangement."],"answer":"Chuẩn liên quan IV(B). Xin written consent của mọi bên liên quan trước khi nhận additional compensation arrangement."},{"id":"E01-13","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette V(A): Manager dùng bảng social media không nguồn để upgrade rating trái phiếu, không kiểm tra risk covenant hoặc issuer cash flow.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến V(A).","Áp dụng đúng yêu cầu V(A) và phân biệt với phương án dễ mắc lỗi: Đăng khuyến nghị vì lượt like cho thấy thông tin đúng.","Hành động phù hợp có thể kiểm chứng: Thực hiện nghiên cứu đủ cơ sở, test source, cash flows, covenant và downside trước recommendation."],"answer":"Chuẩn liên quan V(A). Thực hiện nghiên cứu đủ cơ sở, test source, cash flows, covenant và downside trước recommendation."},{"id":"E01-14","los_ids":["CFA26-10-05-LOS01"],"problem":"Vignette VI(A): Analyst sở hữu lượng lớn cổ phiếu trong coverage nhưng disclosure chỉ có dòng “may have interests” ở cuối trang.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VI(A).","Áp dụng đúng yêu cầu VI(A) và phân biệt với phương án dễ mắc lỗi: Giữ disclosure mơ hồ vì đây là wording pháp chế đã cung cấp.","Hành động phù hợp có thể kiểm chứng: Ưu tiên tránh conflict; nếu được phép tiếp tục thì disclose full, fair, prominent và plain language."],"answer":"Chuẩn liên quan VI(A). Ưu tiên tránh conflict; nếu được phép tiếp tục thì disclose full, fair, prominent và plain language."},{"id":"E02-01","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette I(A): Luật sở tại không cấm một loại giao dịch theo tin mật, nhưng Code CFA Standard II(A) có quy định nghiêm hơn.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(A).","Áp dụng đúng yêu cầu I(A) và phân biệt với phương án dễ mắc lỗi: Giao dịch vì luật địa phương chưa quy định.","Hành động phù hợp có thể kiểm chứng: Vẫn tuân Standard nghiêm hơn, không giao dịch hoặc tipping MNPI, tìm legal guidance khi cần."],"answer":"Chuẩn liên quan I(A). Vẫn tuân Standard nghiêm hơn, không giao dịch hoặc tipping MNPI, tìm legal guidance khi cần."},{"id":"E02-02","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette I(E): Một analyst không tham dự chương trình CME chính thức năm nay nhưng thường xuyên học, kiểm định model và đủ kỹ năng nhiệm vụ.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến I(E).","Áp dụng đúng yêu cầu I(E) và phân biệt với phương án dễ mắc lỗi: Tuyên bố tự động violation vì không có chứng nhận CME 40 giờ.","Hành động phù hợp có thể kiểm chứng: Không tự kết luận vi phạm; I(E) yêu cầu competence thực chất, không bắt buộc số giờ CME cố định."],"answer":"Chuẩn liên quan I(E). Không tự kết luận vi phạm; I(E) yêu cầu competence thực chất, không bắt buộc số giờ CME cố định."},{"id":"E02-03","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette II(A): Analyst tổng hợp filings public, supplier comments không trọng yếu và dữ liệu thống kê rồi suy ra earnings sắp giảm.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến II(A).","Áp dụng đúng yêu cầu II(A) và phân biệt với phương án dễ mắc lỗi: Kết luận cứ có một mẩu nonpublic dù không trọng yếu đều bị cấm dùng.","Hành động phù hợp có thể kiểm chứng: Có thể dùng mosaic theory khi không dựa trên material nonpublic information và research có cơ sở."],"answer":"Chuẩn liên quan II(A). Có thể dùng mosaic theory khi không dựa trên material nonpublic information và research có cơ sở."},{"id":"E02-04","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette III(B): Khuyến nghị giống nhau được gửi cho tất cả clients qua hệ thống có chênh vài giây do server queues, không có ưu tiên có chủ ý.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(B).","Áp dụng đúng yêu cầu III(B) và phân biệt với phương án dễ mắc lỗi: Tuyên bố chắc chắn vi phạm vì vài giây khác nhau.","Hành động phù hợp có thể kiểm chứng: Đánh giá policy phân phối fair; fair dealing không yêu cầu thời điểm giống nhau tuyệt đối nếu không thiên vị."],"answer":"Chuẩn liên quan III(B). Đánh giá policy phân phối fair; fair dealing không yêu cầu thời điểm giống nhau tuyệt đối nếu không thiên vị."},{"id":"E02-05","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette III(E): Một khách hàng hiện tại được yêu cầu khai records theo lệnh tòa hợp pháp, adviser lo ngại confidentiality.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến III(E).","Áp dụng đúng yêu cầu III(E) và phân biệt với phương án dễ mắc lỗi: Giấu records trước lệnh có hiệu lực bất chấp legal obligation.","Hành động phù hợp có thể kiểm chứng: Disclosure có thể phù hợp khi required by law; chỉ tiết lộ phần bắt buộc và ghi nhận cơ sở."],"answer":"Chuẩn liên quan III(E). Disclosure có thể phù hợp khi required by law; chỉ tiết lộ phần bắt buộc và ghi nhận cơ sở."},{"id":"E02-06","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette IV(A): Analyst đang làm tại firm A lập kế hoạch thành lập firm B sau khi nghỉ, chưa tiếp cận/sử dụng dữ liệu client mật.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến IV(A).","Áp dụng đúng yêu cầu IV(A) và phân biệt với phương án dễ mắc lỗi: Tải và dùng client list mật trước nghỉ để khởi động firm B.","Hành động phù hợp có thể kiểm chứng: Việc chuẩn bị tương lai không tự động vi phạm loyalty; không tranh khách hoặc chiếm dụng tài sản/bí mật trong khi còn làm."],"answer":"Chuẩn liên quan IV(A). Việc chuẩn bị tương lai không tự động vi phạm loyalty; không tranh khách hoặc chiếm dụng tài sản/bí mật trong khi còn làm."},{"id":"E02-07","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette IV(C): Supervisor đã có compliance manual nhưng biết nhân viên front-run nhiều lần, không xử lý và không kiểm tra logs.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến IV(C).","Áp dụng đúng yêu cầu IV(C) và phân biệt với phương án dễ mắc lỗi: Coi mọi việc là nhiệm vụ của compliance officer, không cần supervisor theo dõi.","Hành động phù hợp có thể kiểm chứng: Vi phạm nghĩa vụ giám sát nếu không có reasonable efforts; cần remediate và kiểm tra thực thi policy."],"answer":"Chuẩn liên quan IV(C). Vi phạm nghĩa vụ giám sát nếu không có reasonable efforts; cần remediate và kiểm tra thực thi policy."},{"id":"E02-08","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette V(B): Advisor mô tả chiến lược “low volatility” nhưng không trình bày costs, risk limits hoặc underlying leverage.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến V(B).","Áp dụng đúng yêu cầu V(B) và phân biệt với phương án dễ mắc lỗi: Chỉ nêu target return vì clients không hỏi phí.","Hành động phù hợp có thể kiểm chứng: Phải disclose nature of services, related costs, material risks, process changes và facts vs opinions."],"answer":"Chuẩn liên quan V(B). Phải disclose nature of services, related costs, material risks, process changes và facts vs opinions."},{"id":"E02-09","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette V(C): Sau khi nghỉ việc, analyst muốn xóa hết data/model làm cơ sở recommendation để tránh người khác tái sử dụng.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến V(C).","Áp dụng đúng yêu cầu V(C) và phân biệt với phương án dễ mắc lỗi: Xóa ngay vì analyst tự nghĩ mình là người tạo nên sở hữu tuyệt đối.","Hành động phù hợp có thể kiểm chứng: Records là professional/work product phải được duy trì theo luật và firm policy; bàn giao đúng quy trình."],"answer":"Chuẩn liên quan V(C). Records là professional/work product phải được duy trì theo luật và firm policy; bàn giao đúng quy trình."},{"id":"E02-10","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette VI(A): Broker có ownership interest trong security đang phân phối và chỉ disclosure bằng chữ rất nhỏ cuối trang.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VI(A).","Áp dụng đúng yêu cầu VI(A) và phân biệt với phương án dễ mắc lỗi: Giữ chữ nhỏ vì đã technically disclosed.","Hành động phù hợp có thể kiểm chứng: Disclosure đầy đủ, rõ ràng, nổi bật và dễ hiểu; cần avoid nếu conflict không thể kiểm soát."],"answer":"Chuẩn liên quan VI(A). Disclosure đầy đủ, rõ ràng, nổi bật và dễ hiểu; cần avoid nếu conflict không thể kiểm soát."},{"id":"E02-11","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette VI(B): Manager sở hữu cá nhân muốn mua cùng security với client order chưa thực hiện, biết order client lớn có thể làm tăng giá.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VI(B).","Áp dụng đúng yêu cầu VI(B) và phân biệt với phương án dễ mắc lỗi: Mua trước vì personal position nhỏ nên không gây tác động giá.","Hành động phù hợp có thể kiểm chứng: Ưu tiên client/employer order; pre-clear personal trade và không front-run."],"answer":"Chuẩn liên quan VI(B). Ưu tiên client/employer order; pre-clear personal trade và không front-run."},{"id":"E02-12","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette VI(C): Adviser nhận 1% referral fee từ bên cung cấp quỹ và không nói cho clients vì commission do quỹ trả.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VI(C).","Áp dụng đúng yêu cầu VI(C) và phân biệt với phương án dễ mắc lỗi: Không disclosure vì clients không chuyển phí trực tiếp cho adviser.","Hành động phù hợp có thể kiểm chứng: Disclosure nature và amount/arrangement referral fee phù hợp cho employer/clients/prospects."],"answer":"Chuẩn liên quan VI(C). Disclosure nature và amount/arrangement referral fee phù hợp cho employer/clients/prospects."},{"id":"E02-13","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette VII(A): Candidate mô tả những câu hỏi cụ thể vừa thi CFA trong bài social post, nhưng không tiết lộ điểm đạt/trượt.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VII(A).","Áp dụng đúng yêu cầu VII(A) và phân biệt với phương án dễ mắc lỗi: Đăng câu hỏi vì việc chưa biết điểm không liên quan security của exam.","Hành động phù hợp có thể kiểm chứng: Không chia sẻ confidential exam content; có thể nói cảm nhận chung mà không tiết lộ questions/topics confidential."],"answer":"Chuẩn liên quan VII(A). Không chia sẻ confidential exam content; có thể nói cảm nhận chung mà không tiết lộ questions/topics confidential."},{"id":"E02-14","los_ids":["CFA26-10-05-LOS02"],"problem":"Vignette VII(B): Candidate mới đăng ký Level II ghi trên namecard “CFA charterholder Level II” để tăng uy tín.","solution_steps":["Xác định người hành động, quan hệ client/employer, thời điểm và các facts có liên quan đến VII(B).","Áp dụng đúng yêu cầu VII(B) và phân biệt với phương án dễ mắc lỗi: Ghi designation giả vì đã qua một bài thi Level I.","Hành động phù hợp có thể kiểm chứng: Không gọi mình charterholder khi chưa đủ điều kiện; chỉ ghi candidate/passed exam theo cách accurate nếu đúng thực tế."],"answer":"Chuẩn liên quan VII(B). Không gọi mình charterholder khi chưa đủ điều kiện; chỉ ghi candidate/passed exam theo cách accurate nếu đúng thực tế."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống I(A): Một bộ phận Việt Nam xử lý giao dịch tại thị trường nước ngoài nơi regulation cấm phân phối cho retail; công ty mẹ muốn dùng chuẩn thị trường khác ít nghiêm hơn. Cách xử lý phù hợp nhất?","options":["Áp dụng quy định lỏng nhất để chạy kịp chỉ tiêu.","Chỉ cần bỏ qua yêu cầu của I(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Từ chối phát hành tới retail thuộc jurisdiction hạn chế; xác định applicable laws và dùng chuẩn nghiêm hơn, tìm legal counsel."],"correct_option":2,"explanation":"I(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Từ chối phát hành tới retail thuộc jurisdiction hạn chế; xác định applicable laws và dùng chuẩn nghiêm hơn, tìm legal counsel. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-02","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống I(B): Issuer đề nghị research analyst một chuyến công tác “khảo sát” ở resort năm sao và hứa giao thêm deal nếu rating là buy. Cách xử lý phù hợp nhất?","options":["Từ chối hospitality có thể làm ảnh hưởng objectivity; sắp xếp visit theo chính sách độc lập và ghi nhận conflict.","Chỉ cần bỏ qua yêu cầu của I(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Chấp nhận chuyến đi vì issuer nói đây là quà phổ biến."],"correct_option":0,"explanation":"I(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Từ chối hospitality có thể làm ảnh hưởng objectivity; sắp xếp visit theo chính sách độc lập và ghi nhận conflict. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-03","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống I(C): Analyst sửa đường dự báo Excel của nhà tư vấn thành “mô hình độc quyền của tôi” và nói return chắc chắn 18%. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của I(C) nếu giao dịch cuối cùng có lợi nhuận cho client.","Ghi đúng provenance, giữ assumptions và trình bày returns như forecast có uncertainty, không guarantee.","Dùng lời cam kết vì historical return 18% trong một năm."],"correct_option":1,"explanation":"I(C) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Ghi đúng provenance, giữ assumptions và trình bày returns như forecast có uncertainty, không guarantee. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-04","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống I(E): Chuyên viên chuyên equity được chuyển phân tích autocallable note; chưa hiểu barriers nhưng được yêu cầu ký valuation ngay. Cách xử lý phù hợp nhất?","options":["Ký report rồi học thêm sau vì đã làm CFA Level I.","Chỉ cần bỏ qua yêu cầu của I(E) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không ký khi chưa đủ competence; tham vấn chuyên gia/đào tạo, validate risk và model trước khi dùng."],"correct_option":2,"explanation":"I(E) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không ký khi chưa đủ competence; tham vấn chuyên gia/đào tạo, validate risk và model trước khi dùng. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-05","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống II(A): Một nguồn nội bộ cho biết thương vụ mua lại sẽ công bố tuần sau, có khả năng đổi giá cổ phiếu, analyst chưa giao dịch. Cách xử lý phù hợp nhất?","options":["Không trading/tipping theo material nonpublic information; báo compliance và chờ public dissemination.","Chỉ cần bỏ qua yêu cầu của II(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Mua cho tài khoản gia đình vì thông tin chưa xuất hiện trên báo chí."],"correct_option":0,"explanation":"II(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không trading/tipping theo material nonpublic information; báo compliance và chờ public dissemination. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-06","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống II(B): Trader tung các lệnh mua lớn rồi hủy nhanh, mục đích làm người khác tưởng cổ phiếu có demand, sau đó bán hàng đang giữ. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của II(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không tạo deceptive orders/volume; dừng strategy có intent manipulation và báo surveillance.","Tiếp tục vì cuối cùng không khớp các lệnh mua ảo."],"correct_option":1,"explanation":"II(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không tạo deceptive orders/volume; dừng strategy có intent manipulation và báo surveillance. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-07","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống III(A): Portfolio manager chọn broker affiliate với cost cao và execution chậm dù công ty độc lập có giá thực thi tốt hơn. Cách xử lý phù hợp nhất?","options":["Ưu tiên affiliate vì phí giúp tăng doanh thu employer.","Chỉ cần bỏ qua yêu cầu của III(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Đánh giá best execution/client benefit net of costs; tránh giao dịch do quan hệ cá nhân không được công bố."],"correct_option":2,"explanation":"III(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Đánh giá best execution/client benefit net of costs; tránh giao dịch do quan hệ cá nhân không được công bố. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-08","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống III(B): Một khuyến nghị thay đổi từ hold sang sell được gửi riêng cho clients trả phí cao trước một ngày so với nhóm cùng loại research. Cách xử lý phù hợp nhất?","options":["Phân phối fair và objective theo policy/entitlements hợp lý, không tạo thiên vị không phù hợp.","Chỉ cần bỏ qua yêu cầu của III(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Thông báo riêng VIP vì nhóm này đáng được bảo vệ hơn."],"correct_option":0,"explanation":"III(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Phân phối fair và objective theo policy/entitlements hợp lý, không tạo thiên vị không phù hợp. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-09","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống III(C): Khách cần chi phí học phí năm sau nhưng adviser đặt 70% tài sản vào closed-end fund khó rút trong 7 năm. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của III(C) nếu giao dịch cuối cùng có lợi nhuận cho client.","Xác minh liquidity needs, horizon và tổng portfolio; chỉ recommend asset phù hợp toàn bộ constraints.","Khuyên đầu tư vì expected IRR cao nên suitability tự động thỏa mãn."],"correct_option":1,"explanation":"III(C) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Xác minh liquidity needs, horizon và tổng portfolio; chỉ recommend asset phù hợp toàn bộ constraints. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-10","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống III(D): Fund marketing loại bỏ hai tài khoản bị đóng vì lỗ khỏi track record, báo “average năm nay +20%”. Cách xử lý phù hợp nhất?","options":["Chỉ báo cáo số còn active vì tài khoản đóng không còn là client.","Chỉ cần bỏ qua yêu cầu của III(D) nếu giao dịch cuối cùng có lợi nhuận cho client.","Tổng hợp performance fair, accurate, complete theo policy; không cherry-pick accounts/periods."],"correct_option":2,"explanation":"III(D) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Tổng hợp performance fair, accurate, complete theo policy; không cherry-pick accounts/periods. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-11","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống III(E): Advisor gửi bảng clients giàu có cùng số tài khoản cho agency marketing ngoài công ty mà không xin consent. Cách xử lý phù hợp nhất?","options":["Giữ confidentiality và chỉ chia sẻ khi có client permission, legal requirement hoặc exception hợp lệ.","Chỉ cần bỏ qua yêu cầu của III(E) nếu giao dịch cuối cùng có lợi nhuận cho client.","Gửi vì data dùng cho bán hàng và agency có NDA."],"correct_option":0,"explanation":"III(E) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Giữ confidentiality và chỉ chia sẻ khi có client permission, legal requirement hoặc exception hợp lệ. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-12","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống IV(B): Advisor được một khách lớn hứa bonus cá nhân nếu danh mục vượt benchmark, nhưng chưa xin written permission employer. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của IV(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Xin written consent của mọi bên liên quan trước khi nhận additional compensation arrangement.","Nhận tiền và tiết lộ vào cuối năm khi đã hoàn thành mục tiêu."],"correct_option":1,"explanation":"IV(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Xin written consent của mọi bên liên quan trước khi nhận additional compensation arrangement. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-13","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống V(A): Manager dùng bảng social media không nguồn để upgrade rating trái phiếu, không kiểm tra risk covenant hoặc issuer cash flow. Cách xử lý phù hợp nhất?","options":["Đăng khuyến nghị vì lượt like cho thấy thông tin đúng.","Chỉ cần bỏ qua yêu cầu của V(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Thực hiện nghiên cứu đủ cơ sở, test source, cash flows, covenant và downside trước recommendation."],"correct_option":2,"explanation":"V(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Thực hiện nghiên cứu đủ cơ sở, test source, cash flows, covenant và downside trước recommendation. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q01-14","los_ids":["CFA26-10-05-LOS01"],"stem":"Tình huống VI(A): Analyst sở hữu lượng lớn cổ phiếu trong coverage nhưng disclosure chỉ có dòng “may have interests” ở cuối trang. Cách xử lý phù hợp nhất?","options":["Ưu tiên tránh conflict; nếu được phép tiếp tục thì disclose full, fair, prominent và plain language.","Chỉ cần bỏ qua yêu cầu của VI(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Giữ disclosure mơ hồ vì đây là wording pháp chế đã cung cấp."],"correct_option":0,"explanation":"VI(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Ưu tiên tránh conflict; nếu được phép tiếp tục thì disclose full, fair, prominent và plain language. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-01","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống I(A): Luật sở tại không cấm một loại giao dịch theo tin mật, nhưng Code CFA Standard II(A) có quy định nghiêm hơn. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của I(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Vẫn tuân Standard nghiêm hơn, không giao dịch hoặc tipping MNPI, tìm legal guidance khi cần.","Giao dịch vì luật địa phương chưa quy định."],"correct_option":1,"explanation":"I(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Vẫn tuân Standard nghiêm hơn, không giao dịch hoặc tipping MNPI, tìm legal guidance khi cần. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-02","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống I(E): Một analyst không tham dự chương trình CME chính thức năm nay nhưng thường xuyên học, kiểm định model và đủ kỹ năng nhiệm vụ. Cách xử lý phù hợp nhất?","options":["Tuyên bố tự động violation vì không có chứng nhận CME 40 giờ.","Chỉ cần bỏ qua yêu cầu của I(E) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không tự kết luận vi phạm; I(E) yêu cầu competence thực chất, không bắt buộc số giờ CME cố định."],"correct_option":2,"explanation":"I(E) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không tự kết luận vi phạm; I(E) yêu cầu competence thực chất, không bắt buộc số giờ CME cố định. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-03","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống II(A): Analyst tổng hợp filings public, supplier comments không trọng yếu và dữ liệu thống kê rồi suy ra earnings sắp giảm. Cách xử lý phù hợp nhất?","options":["Có thể dùng mosaic theory khi không dựa trên material nonpublic information và research có cơ sở.","Chỉ cần bỏ qua yêu cầu của II(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Kết luận cứ có một mẩu nonpublic dù không trọng yếu đều bị cấm dùng."],"correct_option":0,"explanation":"II(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Có thể dùng mosaic theory khi không dựa trên material nonpublic information và research có cơ sở. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-04","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống III(B): Khuyến nghị giống nhau được gửi cho tất cả clients qua hệ thống có chênh vài giây do server queues, không có ưu tiên có chủ ý. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của III(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Đánh giá policy phân phối fair; fair dealing không yêu cầu thời điểm giống nhau tuyệt đối nếu không thiên vị.","Tuyên bố chắc chắn vi phạm vì vài giây khác nhau."],"correct_option":1,"explanation":"III(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Đánh giá policy phân phối fair; fair dealing không yêu cầu thời điểm giống nhau tuyệt đối nếu không thiên vị. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-05","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống III(E): Một khách hàng hiện tại được yêu cầu khai records theo lệnh tòa hợp pháp, adviser lo ngại confidentiality. Cách xử lý phù hợp nhất?","options":["Giấu records trước lệnh có hiệu lực bất chấp legal obligation.","Chỉ cần bỏ qua yêu cầu của III(E) nếu giao dịch cuối cùng có lợi nhuận cho client.","Disclosure có thể phù hợp khi required by law; chỉ tiết lộ phần bắt buộc và ghi nhận cơ sở."],"correct_option":2,"explanation":"III(E) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Disclosure có thể phù hợp khi required by law; chỉ tiết lộ phần bắt buộc và ghi nhận cơ sở. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-06","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống IV(A): Analyst đang làm tại firm A lập kế hoạch thành lập firm B sau khi nghỉ, chưa tiếp cận/sử dụng dữ liệu client mật. Cách xử lý phù hợp nhất?","options":["Việc chuẩn bị tương lai không tự động vi phạm loyalty; không tranh khách hoặc chiếm dụng tài sản/bí mật trong khi còn làm.","Chỉ cần bỏ qua yêu cầu của IV(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Tải và dùng client list mật trước nghỉ để khởi động firm B."],"correct_option":0,"explanation":"IV(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Việc chuẩn bị tương lai không tự động vi phạm loyalty; không tranh khách hoặc chiếm dụng tài sản/bí mật trong khi còn làm. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-07","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống IV(C): Supervisor đã có compliance manual nhưng biết nhân viên front-run nhiều lần, không xử lý và không kiểm tra logs. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của IV(C) nếu giao dịch cuối cùng có lợi nhuận cho client.","Vi phạm nghĩa vụ giám sát nếu không có reasonable efforts; cần remediate và kiểm tra thực thi policy.","Coi mọi việc là nhiệm vụ của compliance officer, không cần supervisor theo dõi."],"correct_option":1,"explanation":"IV(C) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Vi phạm nghĩa vụ giám sát nếu không có reasonable efforts; cần remediate và kiểm tra thực thi policy. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-08","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống V(B): Advisor mô tả chiến lược “low volatility” nhưng không trình bày costs, risk limits hoặc underlying leverage. Cách xử lý phù hợp nhất?","options":["Chỉ nêu target return vì clients không hỏi phí.","Chỉ cần bỏ qua yêu cầu của V(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Phải disclose nature of services, related costs, material risks, process changes và facts vs opinions."],"correct_option":2,"explanation":"V(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Phải disclose nature of services, related costs, material risks, process changes và facts vs opinions. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-09","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống V(C): Sau khi nghỉ việc, analyst muốn xóa hết data/model làm cơ sở recommendation để tránh người khác tái sử dụng. Cách xử lý phù hợp nhất?","options":["Records là professional/work product phải được duy trì theo luật và firm policy; bàn giao đúng quy trình.","Chỉ cần bỏ qua yêu cầu của V(C) nếu giao dịch cuối cùng có lợi nhuận cho client.","Xóa ngay vì analyst tự nghĩ mình là người tạo nên sở hữu tuyệt đối."],"correct_option":0,"explanation":"V(C) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Records là professional/work product phải được duy trì theo luật và firm policy; bàn giao đúng quy trình. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-10","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống VI(A): Broker có ownership interest trong security đang phân phối và chỉ disclosure bằng chữ rất nhỏ cuối trang. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của VI(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Disclosure đầy đủ, rõ ràng, nổi bật và dễ hiểu; cần avoid nếu conflict không thể kiểm soát.","Giữ chữ nhỏ vì đã technically disclosed."],"correct_option":1,"explanation":"VI(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Disclosure đầy đủ, rõ ràng, nổi bật và dễ hiểu; cần avoid nếu conflict không thể kiểm soát. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-11","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống VI(B): Manager sở hữu cá nhân muốn mua cùng security với client order chưa thực hiện, biết order client lớn có thể làm tăng giá. Cách xử lý phù hợp nhất?","options":["Mua trước vì personal position nhỏ nên không gây tác động giá.","Chỉ cần bỏ qua yêu cầu của VI(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Ưu tiên client/employer order; pre-clear personal trade và không front-run."],"correct_option":2,"explanation":"VI(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Ưu tiên client/employer order; pre-clear personal trade và không front-run. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-12","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống VI(C): Adviser nhận 1% referral fee từ bên cung cấp quỹ và không nói cho clients vì commission do quỹ trả. Cách xử lý phù hợp nhất?","options":["Disclosure nature và amount/arrangement referral fee phù hợp cho employer/clients/prospects.","Chỉ cần bỏ qua yêu cầu của VI(C) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không disclosure vì clients không chuyển phí trực tiếp cho adviser."],"correct_option":0,"explanation":"VI(C) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Disclosure nature và amount/arrangement referral fee phù hợp cho employer/clients/prospects. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-13","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống VII(A): Candidate mô tả những câu hỏi cụ thể vừa thi CFA trong bài social post, nhưng không tiết lộ điểm đạt/trượt. Cách xử lý phù hợp nhất?","options":["Chỉ cần bỏ qua yêu cầu của VII(A) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không chia sẻ confidential exam content; có thể nói cảm nhận chung mà không tiết lộ questions/topics confidential.","Đăng câu hỏi vì việc chưa biết điểm không liên quan security của exam."],"correct_option":1,"explanation":"VII(A) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không chia sẻ confidential exam content; có thể nói cảm nhận chung mà không tiết lộ questions/topics confidential. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."},{"id":"Q02-14","los_ids":["CFA26-10-05-LOS02"],"stem":"Tình huống VII(B): Candidate mới đăng ký Level II ghi trên namecard “CFA charterholder Level II” để tăng uy tín. Cách xử lý phù hợp nhất?","options":["Ghi designation giả vì đã qua một bài thi Level I.","Chỉ cần bỏ qua yêu cầu của VII(B) nếu giao dịch cuối cùng có lợi nhuận cho client.","Không gọi mình charterholder khi chưa đủ điều kiện; chỉ ghi candidate/passed exam theo cách accurate nếu đúng thực tế."],"correct_option":2,"explanation":"VII(B) yêu cầu nhận diện đầy đủ facts và duties. Hành động đúng: Không gọi mình charterholder khi chưa đủ điều kiện; chỉ ghi candidate/passed exam theo cách accurate nếu đúng thực tế. Hai phương án còn lại đánh đồng kết quả/tập quán với trách nhiệm nghề nghiệp hoặc thực hiện điều bị cấm."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 1: xác định sự kiện và chủ thể — cần kiểm tra?","back":"Ở mỗi vignette, trước tiên tách facts đã được cung cấp, assumptions, thời điểm hành vi và vai trò người tham gia: member/candidate, client, employer, counterparties và issuer. Cùng một lời đề nghị quà tặng có thể bị đánh giá khác tùy tính chất, giá trị, timing và ảnh hưởng thực tế tới independence."},{"id":"C01-02","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 2: xác định applicable duties — cần kiểm tra?","back":"Đặt nghĩa vụ Code/Standards và applicable laws lên từng hành vi. Không chỉ tìm từ “conflict” mà cần xác định nghĩa vụ ưu tiên client, duty to employer, market integrity, professional judgment và có hành vi nào thuộc II(A), III(C), IV(B), V(A) hoặc VI(A)."},{"id":"C01-03","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 3: tách facts và hậu quả — cần kiểm tra?","back":"Xác định information public hay nonpublic, materiality, kiểu giao dịch, có intentional market deception, client suitability và trade allocation hay không. Không suy luận “vi phạm” chỉ từ việc sản phẩm giảm giá: loss có thể xảy ra dù process và suitability đã đúng."},{"id":"C01-04","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 4: kiểm tra disclosure, consent và timing — cần kiểm tra?","back":"Disclosure phải đủ và rõ; không phải cứ có một disclaimer là đã đáp ứng. Written consent của tất cả bên liên quan là yêu cầu riêng đối với IV(B); VI(A) yêu cầu avoid hoặc full/fair disclosure; III(E) có ngoại lệ theo law, illegal activities hoặc consent."},{"id":"C01-05","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 5: nguyên tắc multi-standard — cần kiểm tra?","back":"Nếu cùng một nhân viên nhận hidden referral fee, front-run client order và giấu material risk, cần đánh giá VI(C), VI(B), V(B) và III(A) độc lập. Chọn đáp án “best” dựa trên facts và nghĩa vụ ưu tiên, không lựa một Standard duy nhất để bỏ qua những vi phạm còn lại."},{"id":"C01-06","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 6: biện pháp khắc phục — cần kiểm tra?","back":"Hành động đúng thường gồm tránh hoạt động gây xung đột, compliance escalation, independent research review, material disclosure, lưu hồ sơ, phù hợp IPS và ưu tiên client orders. Trong câu CFA, hành động “xin lỗi sau đó” hoặc “nói chung là tuân thủ” không đủ nếu không sửa tác động lên client."},{"id":"C01-07","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 7: quyền hạn và compliance culture — cần kiểm tra?","back":"Professional conduct không chỉ thuộc nhân viên trực tiếp: supervisor phải duy trì reasonable oversight, firm cần ethical culture và incentive. Một môi trường có manual trên giấy nhưng biết nhân viên gian lận và không khắc phục vẫn có governance failure."},{"id":"C01-08","los_ids":["CFA26-10-05-LOS01"],"front":"Bước 8: trade-offs với lợi nhuận — cần kiểm tra?","back":"Đạo đức không bảo đảm mọi khuyến nghị sinh lời; hiệu quả đầu tư xấu sau khi market moves không tự động là misconduct. Thẩm định hành vi nên đánh giá quality of information, process, disclosures, basis, suitability và professional judgment vào lúc quyết định."},{"id":"C02-01","los_ids":["CFA26-10-05-LOS02"],"front":"Các yếu tố biến một hành vi thành violation — cần kiểm tra?","back":"Phân biệt đã có material nonpublic info (II(A)) với mosaic dựa public + nonmaterial private info; phân biệt market-making hợp pháp với spoofing nhằm gây hiểu nhầm. Những chi tiết nhỏ về materiality, intent và timing thường quyết định kết luận."},{"id":"C02-02","los_ids":["CFA26-10-05-LOS02"],"front":"Quyết định conforming không có nghĩa không rủi ro — cần kiểm tra?","back":"Một manager có thể mất tiền trên danh mục nhưng vẫn tuân Standards khi đã đánh giá risk tolerance, investment horizon, data research và risk disclosures đúng. Ngược lại một recommendation sinh lời lớn có thể vẫn vi phạm do front-running, hidden conflicts hoặc thiếu reasonable basis."},{"id":"C02-03","los_ids":["CFA26-10-05-LOS02"],"front":"Consent không thay thế tất cả duties — cần kiểm tra?","back":"Được khách hàng đồng ý một referral fee không miễn written consent required under IV(B) nếu arrangement gây conflict với employer. Disclosure VI(A) không chữa được insider trading II(A), và NDA với agency cũng không tự động tạo ngoại lệ confidentiality III(E)."},{"id":"C02-04","los_ids":["CFA26-10-05-LOS02"],"front":"Thứ tự thời gian giao dịch quan trọng — cần kiểm tra?","back":"VI(B) priority yêu cầu client/employer trades trước personal beneficial ownership; trade nhỏ có thể vẫn front-run. Các lệnh personal preclearance và order timestamps cho thấy process, nhưng dù không làm giá biến động thì front-running vẫn trái chuẩn."},{"id":"C02-05","los_ids":["CFA26-10-05-LOS02"],"front":"Ngoại lệ và những trường hợp hợp pháp — cần kiểm tra?","back":"III(E) cho phép disclosure khi law requires/client permits/illegal activities; I(A) áp dụng strictest relevant requirement; VII(A) vẫn cho phép candidate nêu nhận xét chung về exam, nhưng không tiết lộ confidential questions. Các ngoại lệ này cần đọc đúng facts."},{"id":"C02-06","los_ids":["CFA26-10-05-LOS02"],"front":"Phân biệt duties theo đối tượng — cần kiểm tra?","back":"III(A) Loyalty to Client khác IV(A) Loyalty to Employer; client interest được ưu tiên khi quản lý tài sản, nhưng employee vẫn không được lấy cắp client records khi chuyển việc. Dữ liệu thuộc employer trong employment context không tự thành tài sản riêng analyst."},{"id":"C02-07","los_ids":["CFA26-10-05-LOS02"],"front":"Disclosure effective — cần kiểm tra?","back":"V(B) phải công bố nature of services, costs, methodology, material changes, significant limitations và fact/opinion distinction. VI(A) ưu tiên tránh conflict hoặc full/fair disclosure prominent and plain; VI(C) disclose referral compensation. Một dòng mơ hồ hiếm khi giải quyết cả ba."},{"id":"C02-08","los_ids":["CFA26-10-05-LOS02"],"front":"Cách chọn best answer — cần kiểm tra?","back":"Đối với ba phương án CFA, tìm hành động xử lý đúng bản chất ngay trước giao dịch, có thể triển khai và không làm tổn hại duty khác. Loại phương án cho rằng “không có vi phạm vì luật cho phép”, “không mất tiền nên được phép” hoặc “đã ghi mơ hồ là đủ”."}],"review_status":"targeted_CFAI_Kaplan_SAPP_scenario_based_QA_pass_not_all_534_PDFs"}]);
window.CFA_AUDIT_TOTALS=(function(previous){previous=previous||{};return {...previous,drafted:Math.max(Number(previous.drafted)||0,365),independently_reaudited:Math.max(Number(previous.independently_reaudited)||0,222),scope:"Targeted source review; corrected 2026 Curriculum has 365 unique LOS, not duplicated 366"};})(window.CFA_AUDIT_TOTALS);
